--
-- Table structure for table `analysis_runs`
--

DROP TABLE IF EXISTS `analysis_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `analysis_runs` (
  `project_id` varchar(64) NOT NULL,
  `task_id` varchar(64) DEFAULT NULL,
  `dataset_id` varchar(64) NOT NULL,
  `dataset_version_id` varchar(64) NOT NULL,
  `parent_run_id` varchar(64) DEFAULT NULL COMMENT '稳健性检验的子分析',
  `method` varchar(48) NOT NULL,
  `method_version` varchar(32) NOT NULL,
  `params` text COMMENT 'JSON：完整入参',
  `variables` text COMMENT 'JSON：因变量/自变量/中介/调节',
  `seed` int(11) DEFAULT NULL,
  `bootstrap` int(11) DEFAULT NULL,
