INSERT INTO `database_catalog` VALUES ('Europe PMC','europepmc','生命科学','生命科学与医学文献元数据与部分开放全文。','https://europepmc.org','CC BY / 开放获取','免费开放。',NULL,'{\"api\": true, \"download\": true, \"fulltext\": true}',1,0,1,2,'dbc_0585cd5b709a4cf0d1f2891b23006a1b','2026-09-23 12:13:26','2026-09-23 12:13:26'),('CGSS 中国综合社会调查','cgss','社会科学','中国人民大学中国调查与数据中心发布的年度综合社会调查。','http://cgss.ruc.edu.cn','需申请','需提交申请并说明研究用途。',NULL,'{\"api\": false, \"download\": true, \"fulltext\": false}',0,0,1,4,'dbc_15c3b2e6039285d09e8ef32690456697','2026-09-23 12:13:26','2026-09-23 12:13:26'),('CNKI 中国知网','cnki','综合','中文文献数据库，全文使用需获得授权。','https://www.cnki.net','机构订阅','平台不提供抓取能力；请通过机构订阅合法获取并手动上传。',NULL,'{\"api\": false, \"download\": false, \"fulltext\": false}',0,0,1,5,'dbc_95854ca1bb120308d9510822ee08bc88','2026-09-23 12:13:26','2026-09-23 12:13:26'),('OpenAlex','openalex','综合','开放学术图谱，覆盖论文、作者、机构与引用关系。','https://openalex.org','CC0','免费开放，建议在请求头携带 mailto 以示礼貌。',NULL,'{\"api\": true, \"download\": true, \"fulltext\": false}',1,0,1,0,'dbc_b41269c069d456797a0dbbafef68292e','2026-09-23 12:13:26','2026-09-23 12:13:26'),('CFPS 中国家庭追踪调查','cfps','社会科学','北京大学开放研究数据平台发布的全国性追踪调查。','https://opendata.pku.edu.cn','需注册并同意使用协议','需实名注册、签署数据使用协议，禁止二次分发。',NULL,'{\"api\": false, \"download\": true, \"fulltext\": false}',0,0,1,3,'dbc_d7d320e2b67f13e2ff678309d789b502','2026-09-23 12:13:26','2026-09-23 12:13:26'),('Crossref','crossref','综合','DOI 注册机构元数据，适合做文献身份核验。','https://www.crossref.org','开放元数据','免费开放，遵守礼貌配额。',NULL,'{\"api\": true, \"download\": false, \"fulltext\": false}',1,0,1,1,'dbc_f694e61edfa2968ab51df1c50396e7f9','2026-09-23 12:13:26','2026-09-23 12:13:26');
