INSERT INTO `feasibility_reports` VALUES ('p_2001',1,'dir_ba61ac7726052314bdf95aa10eb83683',1,'{\"query\": \"社交媒体使用强度是否通过自我控制影响大学生手机依赖？社会支持是否调节这一路径？ social media use self-control phone dependence social support\", \"yearFrom\": 2018, \"yearTo\": 2026}','openalex,crossref,europepmc','2026-09-23 12:13:50','projects/p_2001/feasibility/snapshots/lit_120f3f7f543180c899ed45573481cab8.json','801a538754d452629d63385d68c33bf19d7b18061a58c9fb563fe179a4d9d2d8',26,'sample','rubric-1.0',3.6,1,4.5,'原「方案复杂度」维度已转为「方案可执行性分」：分越高越可行。',3.1,'{\"rubricVersion\": \"rubric-1.0\", \"maxScore\": 5.0, \"dimensions\": {\"literatureQuality\": {\"score\": 3.6, \"reason\": \"命中 26 篇文献，年份跨度约 7 年；基于命中文献数量与年份跨度计算。\", \"evidenceBasedOn\": \"26 篇检索命中文献\"}, \"dataAvailability\": {\"score\": 1.0, \"reason\": \"识别到 1 条数据路径；基于识别到的数据路径数量。\", \"evidenceBasedOn\": \"1 条数据路径\"}, \"methodFeasibility\": {\"score\": 4.5, \"reason\": \"识别到 1 条已知方法限制，限制越多可执行性分越低；基于已知方法限制数量反向评估。\", \"evidenceBasedOn\": \"1 条方法限制\"}}, \"literatureQuality\": {\"score\": 3.6, \"reason\": \"命中 26 篇文献，年份跨度约 7 年；基于命中文献数量与年份跨度计算。\"}, \"dataAvailability\": {\"score\": 1.0, \"reason\": \"识别到 1 条数据路径；基于识别到的数据路径数量。\"}, \"methodFeasibility\": {\"score\": 4.5, \"reason\": \"识别到 1 条已知方法限制，限制越多可执行性分越低；基于已知方法限制数量反向评估。\"}, \"complexityNote\": \"原「方案复杂度」维度已转为「方案可执行性分」：分越高越可行。\", \"weights\": {\"literatureQuality\": 0.4, \"dataAvailability\": 0.3, \"methodFeasibility\": 0.3}, \"overallScore\": 3.1, \"insufficientEvidence\": false, \"disclaimer\": \"评分仅用于方案可行性参考，不代表研究结论或录用可能性。\"}','[{\"text\": \"演示模式：该方向在现有证据中的研究空白需结合实际检索结果确认。\", \"evidenceIds\": [\"lit_481fb5ba51c3011b422289f0c862c20a\", \"lit_b9ae2bcf00c2748bc64025cc7a0b73e7\", \"lit_8ea7cccc830164b9c743db74428c1d11\"]}]','[{\"text\": \"演示模式：常见限制包括样本代表性、横向数据无法推断因果。\", \"evidenceIds\": [\"lit_481fb5ba51c3011b422289f0c862c20a\"]}]','[{\"text\": \"演示模式：可考虑公开数据集、问卷自采或平台日志导出。\", \"evidenceIds\": []}]','[{\"text\": \"演示模式：伦理审查与数据授权是主要风险点。\", \"evidenceIds\": []}]','{\"series\": [{\"year\": 2019, \"count\": 1}, {\"year\": 2020, \"count\": 1}, {\"year\": 2021, \"count\": 1}, {\"year\": 2022, \"count\": 4}, {\"year\": 2023, \"count\": 6}, {\"year\": 2024, \"count\": 4}, {\"year\": 2025, \"count\": 6}, {\"year\": 2026, \"count\": 3}], \"totalWithYear\": 26, \"yearRange\": [2019, 2026], \"method\": \"按检索快照的发表年份去重计数（DOI 归一化后）\", \"note\": \"若仅检索了样本，coverage=sample，不能宣称为完整领域趋势。\"}','confirmed',1,1,'usr_54a060709e608a81c6d8637249ea6fc2','fsr_cf9afab0780a1e114ce1b6ca0ff34a70','2026-09-23 12:13:50','2026-09-23 12:13:50');
