CREATE TABLE `manuscript_versions` (
  `project_id` varchar(64) NOT NULL,
  `manuscript_id` varchar(64) NOT NULL,
  `version` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `content_json` text NOT NULL COMMENT '结构化正文 JSON',
  `content_html` text COMMENT '派生视图，已清理脚本与外链',
  `content_md` text,
  `word_count` int(11) NOT NULL,
  `char_count` int(11) NOT NULL COMMENT '统一字符统计规则，不含参考文献',
  `ai_generated_ratio` float NOT NULL,
  `ai_ratio_algorithm_version` varchar(32) NOT NULL,
  `ai_char_count` int(11) NOT NULL,
  `human_char_count` int(11) NOT NULL,
  `mixed_char_count` int(11) NOT NULL,
  `change_note` varchar(512) DEFAULT NULL,
  `content_hash` varchar(64) DEFAULT NULL,
  `created_by` varchar(64) DEFAULT NULL,
  `source` varchar(24) NOT NULL COMMENT 'manual|ai|rollback|import',
  `finalized` tinyint(1) NOT NULL,
  `stale_marks` text COMMENT 'JSON：过期标记（引用核验/评审/匹配）',
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_manuscript_versions_manuscript_id_version` (`manuscript_id`,`version`),
  KEY `ix_manuscript_versions_created_at` (`created_at`),
  KEY `ix_manuscript_versions_project` (`project_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
