DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `kind` varchar(48) NOT NULL,
  `title` varchar(255) NOT NULL,
  `body` text,
  `event_id` varchar(128) NOT NULL,
  `resource_type` varchar(48) DEFAULT NULL,
  `resource_id` varchar(64) DEFAULT NULL,
  `link` varchar(512) DEFAULT NULL,
  `is_read` tinyint(1) NOT NULL,
  `read_at` datetime DEFAULT NULL,
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notifications_user_id_event_id` (`user_id`,`event_id`),
  KEY `ix_notifications_user_read_created` (`user_id`,`is_read`,`created_at`),
  KEY `ix_notifications_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

