INSERT INTO `outlines` VALUES ('p_2001','mns_0a5d3b4c5d8893c042b04da5229ff748',1,0,'[{\"id\": \"sec_intro\", \"title\": \"引言\", \"goal\": \"说明研究背景与问题\", \"dependsOn\": [], \"evidenceIds\": [\"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_48ceb73c7525c363e2f81b9fa2def539\"], \"order\": 1}, {\"id\": \"sec_lit\", \"title\": \"文献综述\", \"goal\": \"归纳已有研究与空白\", \"dependsOn\": [\"sec_intro\"], \"evidenceIds\": [\"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_48ceb73c7525c363e2f81b9fa2def539\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 2}, {\"id\": \"sec_method\", \"title\": \"研究方法\", \"goal\": \"说明样本、变量与分析策略\", \"dependsOn\": [\"sec_lit\"], \"evidenceIds\": [], \"order\": 3}, {\"id\": \"sec_result\", \"title\": \"结果\", \"goal\": \"报告统计结果\", \"dependsOn\": [\"sec_method\"], \"evidenceIds\": [], \"order\": 4}, {\"id\": \"sec_discuss\", \"title\": \"讨论与结论\", \"goal\": \"解释结果、说明限制\", \"dependsOn\": [\"sec_result\"], \"evidenceIds\": [], \"order\": 5}]','{\"literatureIds\": [\"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_48ceb73c7525c363e2f81b9fa2def539\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"count\": 3}',NULL,1,'usr_54a060709e608a81c6d8637249ea6fc2','otl_504542043f291ec2537b56e0cf994e51','2026-09-23 12:14:26','2026-09-23 15:32:20'),('p_2001','mns_0a5d3b4c5d8893c042b04da5229ff748',2,1,'[{\"id\": \"sec_intro\", \"title\": \"引言\", \"goal\": \"基于三篇已核验文献，说明社交媒体使用、被动社交网站使用、问题性手机使用与心理健康/阈下抑郁的研究背景；由于研究问题未明确，需先界定核心问题与研究对象（如大学生），并明确本文仅进行证据范围梳理而非验证因果。\", \"dependsOn\": [], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 1}, {\"id\": \"sec_lit_review\", \"title\": \"文献综述与概念界定\", \"goal\": \"围绕问题性手机使用（PMPU）、被动社交网站使用、FoMO、网络摸鱼、手机/社交媒体使用时长、阈下抑郁及多维心理健康等构念进行界定；可依据 lit_646 标题与摘要片段、lit_3 标题、lit_4 标题与期刊信息归纳主题。限制：lit_3 与 lit_4 的 Crossref 摘要缺失，不能提取样本量、效应量、调节或中介系数。\", \"dependsOn\": [\"sec_intro\"], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 2}, {\"id\": \"sec_theory\", \"title\": \"理论框架与待检验路径\", \"goal\": \"基于已核验标题与摘要信息，整合可能的中介与调节路径：性别/年龄→FoMO、网络摸鱼、手机使用时长、社交媒体使用时长→PMPU；被动社交网站使用→阈下抑郁的调节中介；社交媒体使用与抑郁、焦虑、孤独感及幸福感的关联。限制：现有资料未提供具体路径系数、调节变量名称与模型拟合信息，框架只能作为待验证假设，不能表述为已证实结论。\", \"dependsOn\": [\"sec_lit_review\"], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 3}, {\"id\": \"sec_methods\", \"title\": \"研究方法与证据综合方案\", \"goal\": \"若开展系统综述/元分析，需预先注册并报告检索数据库、检索式、纳排标准、数据提取与质量评价流程。当前资料未提供研究问题、数据库、检索时间、纳入排除标准或原始数据，因此无法确定具体方法；本节只能列出方法学要求，不能编造研究设计。\", \"dependsOn\": [\"sec_theory\"], \"evidenceIds\": [], \"order\": 4}, {\"id\": \"sec_results\", \"title\": \"证据综合结果\", \"goal\": \"按主题汇总三篇文献的可用信息：lit_646 关注 FoMO、网络摸鱼、手机使用时长和社交媒体使用时长在性别/年龄与PMPU关系中的中介作用；lit_3 关注被动社交网站使用与大学生阈下抑郁关系的调节中介模型；lit_4 为社交媒体使用与抑郁、焦虑、孤独感及多种幸福感的元分析。限制：lit_646 摘要不完整，lit_3 与 lit_4 无摘要，不能报告具体效应量、置信区间、异质性或中介/调节结果。\", \"dependsOn\": [\"sec_lit_review\", \"sec_theory\"], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 5}, {\"id\": \"sec_discussion\", \"title\": \"讨论\", \"goal\": \"讨论上述证据的主题交叉点、潜在机制与理论/实践含义，并区分可核验信息与需全文验证的内容。限制：因摘要缺失和研究问题未明确，不能对变量间因果方向、效应大小或群体差异下确定结论。\", \"dependsOn\": [\"sec_results\"], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 6}, {\"id\": \"sec_limitations\", \"title\": \"局限与未来研究方向\", \"goal\": \"说明当前证据基础的限制：研究问题缺失；三篇文献中仅能获取标题和部分元数据；两篇无摘要；无法核验样本、测量工具、统计模型与结果。未来研究应获取全文、明确研究问题，并检验手机/社交媒体使用、FoMO、网络摸鱼与心理健康之间的中介和调节路径。\", \"dependsOn\": [\"sec_discussion\"], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 7}, {\"id\": \"sec_conclusion\", \"title\": \"结论\", \"goal\": \"在现有证据下给出谨慎结论：三篇文献提示社交媒体/手机使用、FoMO、网络摸鱼与心理健康及问题性手机使用之间存在值得整合的研究主题，但不足以形成确定性因果或效应量结论。\", \"dependsOn\": [\"sec_discussion\", \"sec_limitations\"], \"evidenceIds\": [\"lit_646573c1c5521ade083e7d8cf27c77cf\", \"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\"], \"order\": 8}]','{\"literatureIds\": [\"lit_3c92eb40f1d41ce96aafa4cad75fc38a\", \"lit_4b76e00a227c6d5443a75d0633fe5a0b\", \"lit_646573c1c5521ade083e7d8cf27c77cf\"], \"count\": 3}',NULL,0,'usr_54a060709e608a81c6d8637249ea6fc2','otl_f3dbf18ef80953e801c07be7db182595','2026-09-23 15:32:20','2026-09-23 15:32:20');
/*!40000 ALTER TABLE `outlines` ENABLE KEYS */;
UNLOCK TABLES;

