DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `projects` (
  `owner_id` varchar(64) NOT NULL,
  `name` varchar(191) NOT NULL,
  `discipline` varchar(64) DEFAULT NULL COMMENT '学科',
  `design` varchar(64) DEFAULT NULL COMMENT '研究设计/驱动路线',
  `description` text,
  `status` varchar(24) NOT NULL,
  `data_level` varchar(4) NOT NULL,
  `no_train_policy` tinyint(1) NOT NULL COMMENT '项目级「不用于训练」',
  `current_stage` varchar(32) DEFAULT NULL,
  `completion_rate` float NOT NULL,
  `ddl` date DEFAULT NULL COMMENT '纯日期 DDL',
  `ddl_at` datetime DEFAULT NULL COMMENT '带时间 DDL',
  `timezone` varchar(64) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(64) DEFAULT NULL,
  `purge_after` datetime DEFAULT NULL,
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `version` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_projects_ddl` (`ddl`),
  KEY `ix_projects_owner_status` (`owner_id`,`status`),
  KEY `ix_projects_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

