INSERT INTO `projects` VALUES ('usr_54a060709e608a81c6d8637249ea6fc2','社交媒体使用与大学生心理健康','心理学','横断面问卷 + 有调节的中介模型','考察社交媒体使用强度如何通过自我控制影响手机依赖，以及社会支持的调节作用。','active','L1',1,'review_confirmed',0.1667,'2026-11-07',NULL,'Asia/Shanghai',NULL,NULL,NULL,'p_2001','2026-09-23 12:13:28','2026-09-23 12:13:28',1),('usr_54a060709e608a81c6d8637249ea6fc2','短视频使用对青少年注意力的影响','心理学','两波纵向追踪','考察短视频使用时长的变化如何预测注意力指标，检验睡眠时长的中介作用。','active','L1',1,'review_confirmed',0.1667,'2026-10-21',NULL,'Asia/Shanghai',NULL,NULL,NULL,'p_2002','2026-09-23 12:13:28','2026-09-23 12:13:28',1),('usr_54a060709e608a81c6d8637249ea6fc2','正念干预对考试焦虑的随机对照实验','心理学','随机对照实验（RCT）','比较 8 周正念训练组与等待组在考试焦虑与睡眠质量上的差异。','active','L2',1,'review_handled',0.6667,'2026-12-22',NULL,'Asia/Shanghai',NULL,NULL,NULL,'p_2003','2026-09-23 12:13:28','2026-09-23 12:13:28',1),('usr_54a060709e608a81c6d8637249ea6fc2','前端按钮自检项目 20:24:40（已更新）','心理学','数据驱动',NULL,'deleted','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai','2026-09-23 13:03:04','usr_54a060709e608a81c6d8637249ea6fc2','2026-09-30 13:03:04','prj_4c82878a76b2694061fefbb98f983123','2026-09-23 12:24:40','2026-09-23 13:03:57',2),('usr_54a060709e608a81c6d8637249ea6fc2','前端按钮自检项目 20:18:03（已更新）','心理学','数据驱动',NULL,'deleted','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai','2026-09-23 13:03:04','usr_54a060709e608a81c6d8637249ea6fc2','2026-09-30 13:03:04','prj_5bb27edfc0a32afa6d75e87d8c3440a8','2026-09-23 12:18:03','2026-09-23 13:03:57',2),('usr_54a060709e608a81c6d8637249ea6fc2','1','心理学','4',NULL,'active','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai',NULL,NULL,NULL,'prj_73b8bb17461c80e1c572f455d88fe6c3','2026-09-23 15:54:07','2026-09-23 15:54:07',1),('usr_54a060709e608a81c6d8637249ea6fc2','前端按钮自检项目 21:03:04（已更新）','心理学','数据驱动',NULL,'deleted','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai','2026-09-23 13:03:16','usr_54a060709e608a81c6d8637249ea6fc2','2026-09-30 13:03:16','prj_a2a5a6573c44cb5f042a9fc0d53ce706','2026-09-23 13:03:05','2026-09-23 13:03:57',2),('usr_54a060709e608a81c6d8637249ea6fc2','前端按钮自检项目 20:23:33（已更新）','心理学','数据驱动',NULL,'deleted','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai','2026-09-23 13:03:04','usr_54a060709e608a81c6d8637249ea6fc2','2026-09-30 13:03:04','prj_b15ce00aa1691a27a94ab56146132db1','2026-09-23 12:23:34','2026-09-23 13:03:57',2),('usr_54a060709e608a81c6d8637249ea6fc2','前端按钮自检项目 20:21:50（已更新）','心理学','数据驱动',NULL,'deleted','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai','2026-09-23 13:03:04','usr_54a060709e608a81c6d8637249ea6fc2','2026-09-30 13:03:04','prj_ed53205d6eeb06baf57d106724afc6ac','2026-09-23 12:21:50','2026-09-23 13:03:57',2),('usr_54a060709e608a81c6d8637249ea6fc2','前端按钮自检项目 21:08:52（已更新）','心理学','数据驱动',NULL,'deleting','L0',0,'direction_confirmed',0,NULL,NULL,'Asia/Shanghai','2026-09-23 13:09:02','usr_54a060709e608a81c6d8637249ea6fc2','2026-09-30 13:09:02','prj_ff3440707cc540545111bc41f75aa14d','2026-09-23 13:08:53','2026-09-23 13:09:02',2);
