DROP TABLE IF EXISTS `prompt_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prompt_versions` (
  `prompt_id` varchar(64) NOT NULL,
  `scene` varchar(48) NOT NULL,
  `version` varchar(32) NOT NULL,
  `title` varchar(191) NOT NULL,
  `system_template` text NOT NULL,
  `user_template` text,
  `input_schema` text COMMENT 'JSON Schema',
  `output_schema` text COMMENT 'JSON Schema',
  `model_config` text COMMENT 'JSON：温度、max_tokens 等',
  `change_note` varchar(512) DEFAULT NULL,
  `eval_result` text COMMENT 'JSON：评测结果',
  `is_active` tinyint(1) NOT NULL,
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_prompt_versions_prompt_id_version` (`prompt_id`,`version`),
  KEY `ix_prompt_versions_scene_active` (`scene`,`is_active`),
  KEY `ix_prompt_versions_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

