DROP TABLE IF EXISTS `qa_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qa_records` (
  `project_id` varchar(64) NOT NULL,
  `asked_by` varchar(64) DEFAULT NULL,
  `question` text NOT NULL,
  `answer` text,
  `evidence_ids` text COMMENT 'JSON 数组',
  `citations` text COMMENT 'JSON：定位信息',
  `insufficient_evidence` tinyint(1) NOT NULL,
  `scope_literature_ids` text,
  `ai_call_id` varchar(64) DEFAULT NULL,
  `ai_mock` tinyint(1) NOT NULL,
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_qa_records_project_created` (`project_id`,`created_at`),
  KEY `ix_qa_records_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

