DROP TABLE IF EXISTS `review_issues`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review_issues` (
  `project_id` varchar(64) NOT NULL,
  `run_id` varchar(64) NOT NULL,
  `seq` int(11) NOT NULL,
  `severity` varchar(16) NOT NULL COMMENT 'critical|disputed|style',
  `source` varchar(16) NOT NULL COMMENT 'rule|model|corpus',
  `category` varchar(48) DEFAULT NULL COMMENT 'citation_missing|stat_mismatch|material_incomplete|...',
  `section_id` varchar(64) DEFAULT NULL,
  `block_id` varchar(64) DEFAULT NULL,
  `anchor_text_hash` varchar(64) DEFAULT NULL,
  `anchor_excerpt` text,
  `title` varchar(255) NOT NULL,
  `detail` text,
  `suggestion` text COMMENT '建议补丁',
  `suggestion_patch` text COMMENT 'JSON：结构化建议',
  `evidence_ids` text COMMENT 'JSON 数组',
  `state` varchar(16) NOT NULL,
  `state_reason` text COMMENT '忽略/争议理由',
  `resolution_version` int(11) DEFAULT NULL COMMENT '已解决需关联修订版本',
  `resolution_note` text,
  `handled_by` varchar(64) DEFAULT NULL,
  `handled_at` datetime DEFAULT NULL,
  `creates_blocker` tinyint(1) NOT NULL COMMENT '严重问题默认产生导出阻断',
  `stale` tinyint(1) NOT NULL,
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_review_issues_project_severity` (`project_id`,`severity`),
  KEY `ix_review_issues_run_state` (`run_id`,`state`),
  KEY `ix_review_issues_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

