CREATE TABLE `review_runs` (
  `project_id` varchar(64) NOT NULL,
  `task_id` varchar(64) DEFAULT NULL,
  `manuscript_id` varchar(64) NOT NULL,
  `manuscript_version` int(11) NOT NULL,
  `journal_id` varchar(64) DEFAULT NULL,
  `verification_run_id` varchar(64) DEFAULT NULL,
  `analysis_run_id` varchar(64) DEFAULT NULL,
  `config` text COMMENT 'JSON：评审配置',
  `input_snapshot_hash` varchar(64) DEFAULT NULL,
  `review_mode` varchar(24) NOT NULL,
  `corpus_paper_count` int(11) NOT NULL,
  `corpus_comment_count` int(11) NOT NULL,
  `corpus_note` varchar(512) DEFAULT NULL,
  `issue_total` int(11) NOT NULL,
  `critical_count` int(11) NOT NULL,
  `disputed_count` int(11) NOT NULL,
  `style_count` int(11) NOT NULL,
  `open_count` int(11) NOT NULL,
  `accepted_count` int(11) NOT NULL,
  `ignored_count` int(11) NOT NULL,
  `resolved_count` int(11) NOT NULL,
  `status` varchar(24) NOT NULL,
  `stale` tinyint(1) NOT NULL,
  `ai_mock` tinyint(1) NOT NULL,
  `summary` text,
  `created_by` varchar(64) DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_review_runs_manuscript_version` (`manuscript_id`,`manuscript_version`),
  KEY `ix_review_runs_created_at` (`created_at`),
  KEY `ix_review_runs_project_created` (`project_id`,`created_at`)
