--
-- Table structure for table `tasks`
--

DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tasks` (
  `kind` varchar(64) NOT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `created_by` varchar(64) DEFAULT NULL,
  `input_snapshot` text COMMENT 'JSON：任务输入快照',
  `input_hash` varchar(64) DEFAULT NULL,
  `idempotency_key` varchar(128) DEFAULT NULL,
  `state` varchar(24) NOT NULL,
  `stage` varchar(64) DEFAULT NULL,
  `progress` float DEFAULT NULL,
  `completed_units` int(11) DEFAULT NULL,
  `total_units` int(11) DEFAULT NULL,
  `priority` int(11) NOT NULL COMMENT '数值越小优先级越高',
  `attempt` int(11) NOT NULL,
  `max_attempts` int(11) NOT NULL,
  `lease_until` datetime DEFAULT NULL,
  `worker_id` varchar(64) DEFAULT NULL,
  `heartbeat_at` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `cancel_requested_at` datetime DEFAULT NULL,
  `result_ref` varchar(255) DEFAULT NULL COMMENT '结果引用：runId / reportId 等',
  `result_meta` text COMMENT 'JSON',
  `error_code` int(11) DEFAULT NULL,
  `error_message` varchar(1024) DEFAULT NULL,
  `error_detail` text,
  `quota_account_id` varchar(64) DEFAULT NULL COMMENT '预占额度所属账本',
  `quota_period` varchar(16) DEFAULT NULL COMMENT '预占额度所属周期 YYYY-MM',
  `id` varchar(64) NOT NULL COMMENT '带前缀的不可预测 ID',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_tasks_state_lease` (`state`,`lease_until`),
  KEY `ix_tasks_project_created` (`project_id`,`created_at`),
  KEY `ix_tasks_kind_state` (`kind`,`state`),
  KEY `ix_tasks_created_at` (`created_at`),
  KEY `ix_tasks_idem` (`created_by`,`idempotency_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

